function(container, tables) {
    // 業務ロジックモジュールをインポート
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.businessLogic || {};

    // 予測精度監視に必要な要素を取得
    const refreshBtn = container.querySelector('#refresh-accuracy-btn');
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const periodSelect = container.querySelector('#period-select');
    const accuracyTable = container.querySelector('#accuracy-table tbody');
    const accuracyChart = container.querySelector('#accuracy-chart');
    const alertsContainer = container.querySelector('#accuracy-alerts');

    // 商品・店舗選択肢を初期化
    function initializeSelectors() {
        // 商品データを取得して選択肢に設定
        window.aivicApi.list('products').then(products => {
            productSelect.innerHTML = '<option value="">全商品</option>';
            products.forEach(product => {
                const option = document.createElement('option');
                option.value = product.id;
                option.textContent = product.name;
                productSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('商品データの取得に失敗しました');
        });

        // 店舗データを取得して選択肢に設定
        window.aivicApi.list('stores').then(stores => {
            storeSelect.innerHTML = '<option value="">全店舗</option>';
            stores.forEach(store => {
                const option = document.createElement('option');
                option.value = store.id;
                option.textContent = store.name;
                storeSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('店舗データの取得に失敗しました');
        });
    }

    // 予測精度を計算して表示
    async function calculateAndDisplayAccuracy() {
        try {
            const productId = productSelect.value;
            const storeId = storeSelect.value;
            const period = periodSelect.value;

            // 比較期間の妥当性をチェック
            if (!validateComparisonPeriod(period)) {
                window.aivicNotify.error('選択された期間は比較に適していません');
                return;
            }

            // 売上データを収集
            const salesData = await collectSalesData(productId, storeId, period);

            if (!salesData || salesData.length === 0) {
                window.aivicNotify.error('指定条件での売上データが見つかりません');
                return;
            }

            // 有効な商品データをフィルタリング
            const validData = filterValidProductData(salesData);

            // 予測データを取得
            const predictions = await window.aivicApi.list('predictions', {
                productId: productId,
                storeId: storeId,
                period: period
            });

            // 精度計算
            const accuracyResults = calculateAccuracyMetrics(validData, predictions);

            // 結果を表示
            displayAccuracyTable(accuracyResults);
            displayAccuracyChart(accuracyResults);
            displayAccuracyAlerts(accuracyResults);

            window.aivicNotify.success('予測精度の更新が完了しました');

        } catch (error) {
            console.error('予測精度計算エラー:', error);
            window.aivicNotify.error('予測精度の計算に失敗しました');
        }
    }

    // 精度指標を計算
    function calculateAccuracyMetrics(actualData, predictions) {
        const results = [];

        predictions.forEach(prediction => {
            const actual = actualData.find(data => 
                data.productId === prediction.productId && 
                data.storeId === prediction.storeId &&
                data.date === prediction.date
            );

            if (actual) {
                const mape = Math.abs((actual.sales - prediction.predictedSales) / actual.sales) * 100;
                const mae = Math.abs(actual.sales - prediction.predictedSales);
                const rmse = Math.pow(actual.sales - prediction.predictedSales, 2);

                results.push({
                    productId: prediction.productId,
                    storeId: prediction.storeId,
                    date: prediction.date,
                    actual: actual.sales,
                    predicted: prediction.predictedSales,
                    mape: mape,
                    mae: mae,
                    rmse: rmse,
                    accuracy: 100 - mape
                });
            }
        });

        return results;
    }

    // 精度テーブルを表示
    function displayAccuracyTable(results) {
        accuracyTable.innerHTML = '';

        results.forEach(result => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${result.productId}</td>
                <td>${result.storeId}</td>
                <td>${result.date}</td>
                <td>${result.actual.toLocaleString()}</td>
                <td>${result.predicted.toLocaleString()}</td>
                <td>${result.accuracy.toFixed(2)}%</td>
                <td>${result.mape.toFixed(2)}%</td>
                <td>${result.mae.toFixed(0)}</td>
            `;

            // 精度が低い場合は警告色
            if (result.accuracy < 80) {
                row.classList.add('warning');
            }

            accuracyTable.appendChild(row);
        });
    }

    // 精度チャートを表示
    function displayAccuracyChart(results) {
        const chartData = results.map(result => ({
            x: result.date,
            y: result.accuracy,
            productId: result.productId
        }));

        // 簡易チャート表示（実際の実装では Chart.js等を使用）
        accuracyChart.innerHTML = `
            <div class="chart-placeholder">
                <p>精度推移グラフ</p>
                <p>平均精度: ${(chartData.reduce((sum, d) => sum + d.y, 0) / chartData.length).toFixed(2)}%</p>
            </div>
        `;
    }

    // 精度アラートを表示
    function displayAccuracyAlerts(results) {
        alertsContainer.innerHTML = '';

        const lowAccuracyItems = results.filter(result => result.accuracy < 80);

        if (lowAccuracyItems.length > 0) {
            const alertDiv = document.createElement('div');
            alertDiv.className = 'alert alert-warning';
            alertDiv.innerHTML = `
                <h4>精度低下アラート</h4>
                <p>${lowAccuracyItems.length}件の商品で予測精度が80%を下回っています。</p>
                <ul>
                    ${lowAccuracyItems.map(item => 
                        `<li>商品ID: ${item.productId}, 店舗ID: ${item.storeId}, 精度: ${item.accuracy.toFixed(2)}%</li>`
                    ).join('')}
                </ul>
            `;
            alertsContainer.appendChild(alertDiv);
        } else {
            const successDiv = document.createElement('div');
            successDiv.className = 'alert alert-success';
            successDiv.innerHTML = '<p>すべての予測精度が基準値を満たしています。</p>';
            alertsContainer.appendChild(successDiv);
        }
    }

    // イベントハンドラーを設定
    if (refreshBtn) {
        refreshBtn.addEventListener('click', calculateAndDisplayAccuracy);
    }

    // フィルター変更時の自動更新
    [productSelect, storeSelect, periodSelect].forEach(select => {
        if (select) {
            select.addEventListener('change', calculateAndDisplayAccuracy);
        }
    });

    // 初期化実行
    initializeSelectors();

    // 初期データ読み込み
    setTimeout(() => {
        calculateAndDisplayAccuracy();
    }, 500);
}
